function persist(){write('fp2-services',services);write('fp2-favorites',favorites);write('fp2-bookings',bookings);write('fp2-slots',slots);write('fp2-apps',applications);write('fp2-profile',profile)}function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),3500)}function navto(p){if(p!=='home')stopVoice();page=p;closeModal();location.hash=role+'/'+p;render();window.scrollTo(0,0)}function switchRole(r){stopVoice();role=r;page=r==='user'?'home':'overview';navto(page)}function switchLang(l){stopVoice();lang=l;write('fp2-lang',l);render();if(role==='user'&&page==='home')speakWelcome()}
const navs=()=>role==='user'?[['home','⌂',t('الرئيسية','Home')],['chat','✧',t('مساعدتي Nova','Nova assistant')],['discover','⌕',t('اكتشاف الخدمات','Explore services')],['saved','♡',t('المفضلة','Saved')],['bookings','▦',t('حجوزاتي','My bookings')],['preferences','⚙',t('تفضيلاتي','Preferences')]]:role==='provider'?[['overview','◈',t('نظرة عامة','Overview')],['profile','◎',t('ملف المزوّد','Provider profile')],['services','▤',t('الخدمات والأسعار','Services & prices')],['availability','▦',t('التقويم والمواعيد','Availability')],['requests','☷',t('طلبات الحجز','Booking requests')]]:[['overview','◈',t('نظرة عامة','Overview')],['applications','▣',t('طلبات الانضمام','Applications')],['providers','◎',t('إدارة المزوّدين','Providers')],['users','♙',t('إدارة المستخدمين','Users')],['moderation','☆',t('التصنيفات والتقييمات','Categories & reviews')]];
function shell(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';$('root').innerHTML=`<div class="layout"><aside class="side"><a class="logo" href="#user/home">Fit<span>Path<b>✦</b></span><span class="mark">↗</span></a><div class="tagline">${t('خطوة أقرب لحياة بتشبهك','One step closer to your kind of wellbeing')}</div><div class="role-label">${role==='user'?t('مساحتك الشخصية','YOUR SPACE'):role==='provider'?t('مساحة مزوّد الخدمة','PROVIDER WORKSPACE'):t('إدارة المنصة','ADMINISTRATION')}</div><nav class="nav">${navs().map(([p,i,n])=>`<button class="${page===p?'active':''}" onclick="navto('${p}')"><i>${i}</i>${n}</button>`).join('')}</nav><div class="side-note"><b>✧ ${role==='user'?t('معكِ، خطوة بخطوة','With you, step by step'):t('تجربة مترابطة','A connected experience')}</b>${role==='user'?t('احكي لـNova شو بتدوري عليه، وخلي البداية أسهل.','Tell Nova what you need. Make your first step easier.'):t('الخدمات والمواعيد والحجوزات مرتبطة على هذا المتصفح.','Services, availability and bookings stay connected on this browser.')}<br><span class="small-note">${t('نموذج تفاعلي ببيانات تجريبية','Interactive prototype with sample data')}</span></div><div class="side-bottom">${t('عمّان، الأردن','Amman, Jordan')} · FitPath © 2026</div></aside><main class="main"><header><div class="greeting">${role==='user'?t('أهلًا فيكِ في FitPath 🌿','Welcome to FitPath 🌿'):role==='provider'?t('يوم جديد، وخطوات أوضح 🌿','A clearer view of your day 🌿'):t('مساحة إدارة FitPath','FitPath administration')}<small>${t('خيارات مناسبة، وقرارات أوضح','Better choices. A clearer path.')}</small></div><a class="mobile-brand" href="#user/home">FitPath ✦</a><div class="account"><div class="lang"><button class="${lang==='ar'?'active':''}" onclick="switchLang('ar')" lang="ar">العربية</button><button class="${lang==='en'?'active':''}" onclick="switchLang('en')" lang="en">English</button></div><select class="role-select" aria-label="${t('استعراض الدور التجريبي','Preview demo role')}" onchange="switchRole(this.value)"><option value="user" ${role==='user'?'selected':''}>${t('المستخدم','User experience')}</option><option value="provider" ${role==='provider'?'selected':''}>${t('مزوّد الخدمة','Provider workspace')}</option><option value="admin" ${role==='admin'?'selected':''}>${t('الأدمن','Admin workspace')}</option></select></div></header><div class="content" id="app"></div></main></div>`}
const heading=(k,h,s)=>`<div class="eyebrow">${k}</div><h1>${h}</h1><div class="muted">${s}</div>`,title=(a,e,sa,se)=>heading(t('فيت باث / '+(role==='user'?'اكتشفي':role==='provider'?'مزوّد الخدمة':'الإدارة'),'FITPATH / '+(role==='user'?'DISCOVER':role.toUpperCase())),t(a,e),t(sa,se)),pill=s=>`<span class="status ${s}">${status(s)}</span>`,note=()=>'',nova=()=>`<div class="nova-scene"><span class="float-tag tag-a">✧ ${t('خيارات تناسبك إنتِ','Made for your kind of journey')}</span><div class="orb"><span class="antenna"></span><div class="face"><span class="eye"></span><span class="eye"></span><span class="smile"></span></div></div><span class="float-tag tag-b">🌱 ${t('على مهلك، بطريقتك','Your path. Your pace.')}</span></div>`;
function cards(list){return list.length?`<div class="cards">${list.map(x=>`<article class="card"><div class="cover"><img src="${images[x.cat]}" alt="${esc(cat(x.cat))}" loading="lazy"><button class="heart" aria-label="${t('حفظ أو إزالة من المفضلة','Save or unsave')}" onclick="favorite(${x.id})">${favorites.includes(x.id)?'♥':'♡'}</button><span class="pill">${cat(x.cat)}</span></div><div class="card-body"><h3>${esc(text(x.name))}</h3><div class="location">⌖ ${area(x.area)} · ${x.duration} ${t('دقيقة','min')}</div><div class="chips">${x.tags.map(v=>`<span class="chip">${esc(text(v))}</span>`).join('')}</div><div class="card-foot"><span class="price">${money(x.price)} <small>/ ${unit(x.unit)}</small></span><button class="link-btn" onclick="openDetail(${x.id})">${t('التفاصيل ←','Details →')}</button><button class="link-btn" onclick="toggleCompare(${x.id})">${compare.includes(x.id)?'✓':'+ '}${t('مقارنة','Compare')}</button></div></div></article>`).join('')}</div>`:empty(t('ما في نتائج مطابقة حاليًا','No matching options right now'),t('جرّبي تعديل الشروط أو توسيع المنطقة.','Try adjusting your criteria or expanding the area.'))}function empty(h,s){return `<div class="empty"><h3>${h}</h3><p>${s}</p></div>`}function composer(){return `<form class="composer" onsubmit="ask(event)"><span>✧</span><input id="query" aria-label="${t('طلبك لـNova','Your request to Nova')}" placeholder="${t('بدي بيلاتس بمرج الحمام تحت 35 دينار…','Pilates in Marj Al-Hamam under 35 JOD…')}" maxlength="500" required><button class="send" aria-label="${t('إرسال','Send')}">${t('←','→')}</button></form>`}
function home(){return heading(t('رحلتك، على طريقتك','YOUR PATH, YOUR PACE'),t('كل رحلة حلوة، <span>بتبدأ بخطوة.</span>','Every good journey <span>starts with a step.</span>'),t('اكتشفي أماكن وخبراء يناسبوا هدفك، وقتك، وميزانيتك.','Discover spaces and experts that fit your goals, schedule and budget.'))+`<section class="hero"><div class="hero-copy"><span class="pill"><span class="dot"></span>${t('رفيقتك لبداية أسهل','Your companion for an easier start')}</span><h2>${t('أهلًا وسهلًا، أنا نوفا!','Hello, I’m Nova!')}</h2><p>${t('مساعدتك الشخصية لبداية أكثر صحة ونشاط. نلاقي جيم، أخصائي تغذية، أو مدرّبك الشخصي؟','Your personal companion for a healthier, more active life. Shall we find a gym, a dietitian, or your personal trainer?')}</p><div class="nova-live"><span class="live-dot"></span><span id="voice-status" role="status">${t('نوفا ترحّب فيكِ','Nova is welcoming you')}</span><span class="sound-waves" aria-hidden="true"><i></i><i></i><i></i><i></i></span></div>${composer()}<div class="quick"><button onclick="quick('${t('بيلاتس بمرج الحمام تحت 35 دينار','Pilates in Marj Al-Hamam under 35 JOD')}')">${t('🧘 بيلاتس قريب مني','🧘 Pilates nearby')}</button><button onclick="browse('diet')">${t('🥗 أخصائية تغذية','🥗 A dietitian')}</button><button onclick="browse('trainer')">${t('↗ تدريب من البيت','↗ Training from home')}</button></div><div class="small-note" style="margin-top:10px">${t('المحادثة محاكاة محلية. لا يتم تشغيل الميكروفون.','Chat is a local simulation. Your microphone is never activated.')}</div></div>${nova()}</section><div class="section-title"><h2>${t('شو حابة تستكشفي اليوم؟','What would you like to explore?')}</h2><span class="small-note">${t('ثلاث طرق، لرحلة واحدة','Three paths. One journey.')}</span></div><div class="categories">${[['gym','♧',t('مكان يناسب نشاطك وراحتك','Find a space that feels right')],['diet','◒',t('خطوة لعادات غذائية أفضل','Build better everyday habits')],['trainer','↗',t('تدريب مرن، وين ما كنتِ','Flexible training, wherever you are')]].map(([c,i,s])=>`<button class="category" onclick="browse('${c}')"><span class="cat-icon">${i}</span><h3>${cat(c)}</h3><p>${s}</p><span class="arrow">${t('اكتشفي الخيارات ←','Explore options →')}</span></button>`).join('')}</div><div class="section-title"><h2>${t('إلهام لبدايتك القادمة','Inspiration for your next step')}</h2><button onclick="browse('all')">${t('كل الخيارات ←','View all →')}</button></div>${cards(services.filter(x=>x.status==='approved').slice(0,3))}`}
function browse(c){filterState.cat=c;navto('discover')}function discover(){let f=filterState,list=services.filter(x=>x.status==='approved'&&(f.cat==='all'||x.cat===f.cat)&&(f.area==='all'||x.area===f.area)&&(f.unit==='all'||x.unit===f.unit)&&(f.budget===''||x.price<=+f.budget));return title('خيارات أكثر. <span>حيرة أقل.</span>','More possibilities. <span>Less guesswork.</span>','فلترة واضحة حسب الخدمة والمنطقة ووحدة السعر.','Clear filters by service, area and pricing unit.')+`<form class="filters standard-filters" onsubmit="applyFilters(event)"><div class="filter-heading">${t('الفلاتر','Filters')}</div><label class="filter-field"><span>${t('نوع الخدمة','Category')}</span><select id="fc" aria-label="${t('نوع الخدمة','Service category')}"><option value="all">${t('كل الخدمات','All services')}</option>${['gym','diet','trainer'].map(c=>`<option value="${c}" ${f.cat===c?'selected':''}>${cat(c)}</option>`).join('')}</select></label><label class="filter-field"><span>${t('المنطقة','Area')}</span><select id="fa" aria-label="${t('المنطقة','Area')}"><option value="all">${t('كل المناطق','All areas')}</option>${['marj','abdoun','khalda','online'].map(a=>`<option value="${a}" ${f.area===a?'selected':''}>${area(a)}</option>`).join('')}</select></label><label class="filter-field"><span>${t('وحدة السعر','Pricing unit')}</span><select id="fu" aria-label="${t('وحدة السعر','Price unit')}"><option value="all">${t('كل وحدات السعر','All pricing units')}</option>${['class','consultation','session','month'].map(u=>`<option value="${u}" ${f.unit===u?'selected':''}>${t('لكل ','Per ')}${unit(u)}</option>`).join('')}</select></label><label class="filter-field"><span>${t('أقصى سعر','Maximum price')}</span><input id="fb" type="number" min="0" value="${esc(f.budget)}" aria-label="${t('أقصى سعر','Maximum price')}" placeholder="${t('أقصى سعر بالدينار','Max price in JOD')}"></label><button class="primary">${t('تطبيق','Apply')}</button><button type="button" class="secondary" onclick="filterState={cat:filterState.cat,area:'all',unit:'all',budget:''};render()">${t('مسح','Reset')}</button></form><p class="muted">${list.length} ${t('خيارات · انتبهي لوحدة السعر عند المقارنة','options · Check pricing units when comparing')}</p>${cards(list)}`}
function applyFilters(e){e.preventDefault();filterState={cat:$('fc').value,area:$('fa').value,unit:$('fu').value,budget:$('fb').value};render()}function ask(e){e.preventDefault();quick($('query').value)}function quick(q){query=q;const s=q.toLowerCase().replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)),b=s.match(/\d+/),c=/تغذي|أخصائ|diet|nutrition/.test(s)?'diet':/مدرب|تدريب|البيت|train|coach/.test(s)?'trainer':'gym';chatResults=services.filter(x=>x.status==='approved'&&x.cat===c&&(!/بيلاتس|pilates/.test(s)||x.activity==='pilates')&&(!/مرج|marj/.test(s)||x.area==='marj')&&(!b||x.price<=+b[0]));navto('chat')}
function chat(){return title('خلينا نلاقي <span>الأنسب إلك.</span>','Let’s find <span>your kind of fit.</span>','محاكاة بحث تجريبية بالعربية والإنجليزية، وليست AI متصلة.','A sample Arabic and English search simulation, not a connected AI service.')+(query?`<div class="chat-row user">${esc(query)}</div><div class="chat-row nova"><b>✧ Nova</b><br>${chatResults.length?t('هاي خيارات من الكتالوج التجريبي حسب نوع الخدمة والمنطقة والميزانية المذكورة.','Here are options from the sample catalogue based on the category, area and budget I could identify.'):t('ما لقيت تطابقًا. جرّبي توسيع المنطقة أو تعديل الميزانية.','I couldn’t find a match. Try a broader area or a different budget.')}<br><small class="muted">${t('النموذج يفهم طلبات محدودة؛ راجعي وحدة السعر وتفاصيل كل خدمة.','This demo understands limited requests. Check the pricing unit and service details.')}</small></div>${cards(chatResults)}`:`<div class="chat-row nova">✧ ${t('أهلًا! احكيلي نوع الخدمة والمنطقة والميزانية. مثلًا: بيلاتس بمرج الحمام تحت 35 دينار.','Hello! Tell me the service, area and budget. For example: Pilates in Marj Al-Hamam under 35 JOD.')}</div>`)+composer()}
function openDetail(id){selected=id;write('fp2-selected',id);navto('detail')}function details(){const x=service(selected);if(!x||x.status!=='approved')return empty(t('الخدمة غير متاحة','Service unavailable'),t('ارجعي للاستكشاف لتشوفي خيارات أخرى.','Explore other available options.'));return `<button class="secondary" onclick="browse('${x.cat}')">${t('→ رجوع للاستكشاف','← Back to explore')}</button><section class="detail-top"><img src="${images[x.cat]}" alt="${esc(cat(x.cat))}"><div><span class="pill">${t('خدمة تجريبية · اعتماد غير متحقق','Sample service · Credentials not verified')}</span><h2>${esc(text(x.name))}</h2><p class="muted">⌖ ${area(x.area)} · ${x.duration} ${t('دقيقة','minutes')}</p><p>${esc(text(x.desc))}</p><div class="chips">${x.tags.map(a=>`<span class="chip">${esc(text(a))}</span>`).join('')}</div><h3>${money(x.price)} <small class="muted">/ ${unit(x.unit)}</small></h3><button class="primary" onclick="book(${x.id})">${t('اختاري موعدك ←','Choose a time →')}</button> <button class="secondary" onclick="favorite(${x.id})">${favorites.includes(x.id)?'♥':'♡'} ${t('حفظ','Save')}</button></div></section><div class="panel"><h2>${t('الخدمة والمواعيد','Service & availability')}</h2><p class="muted">${t('المواعيد الظاهرة من جدول مزوّد الخدمة في هذا النموذج.','Available times come from the provider’s calendar in this prototype.')}</p><div class="schedule">${available(x.id).map(s=>`<div><b>${s.date}</b><p>${s.time}</p><span class="small-note">${remaining(s)} ${t('أماكن متاحة','spaces available')}</span></div>`).join('')||t('لا توجد مواعيد مضافة حاليًا.','No available times have been added yet.')}</div></div><div class="status-note">${t('هذا حجز طلب بانتظار موافقة المزوّد. لا يتم الدفع أو التواصل مع مزوّد فعلي. التقييمات غير متاحة قبل إكمال حجز تجريبي.','Bookings are requests awaiting provider approval. No payment or real provider contact occurs. Reviews become available after a demo booking is completed.')}</div>`}
function favorite(id){favorites=favorites.includes(id)?favorites.filter(a=>a!==id):[...favorites,id];persist();render();toast(t('تم تحديث المفضلة','Saved list updated'))}function toggleCompare(id){if(compare.includes(id))compare=compare.filter(a=>a!==id);else if(compare.length<3)compare.push(id);else return toast(t('حتى 3 خدمات للمقارنة','Compare up to 3 services'));render()}function compareView(){return title('قارني، <span>واختاري براحتك.</span>','Compare. <span>Choose with confidence.</span>','قارني السعر حسب وحدته، بدون نسب تطابق غير مفسرة.','Compare prices with their units, without unexplained match scores.')+(compare.length?`<div class="table-wrap"><table><tr><th>${t('الخدمة','Service')}</th>${compare.map(id=>`<th>${esc(text(service(id).name))}</th>`).join('')}</tr>${[[t('المنطقة','Area'),x=>area(x.area)],[t('السعر','Price'),x=>money(x.price)],[t('وحدة السعر','Price unit'),x=>unit(x.unit)],[t('المدة','Duration'),x=>x.duration+' '+t('دقيقة','min')]].map(([h,fn])=>`<tr><th>${h}</th>${compare.map(id=>`<td>${fn(service(id))}</td>`).join('')}</tr>`).join('')}<tr><th>${t('الخطوة القادمة','Next step')}</th>${compare.map(id=>`<td><button class="primary" onclick="openDetail(${id})">${t('التفاصيل','Details')}</button></td>`).join('')}</tr></table></div>`:empty(t('اختاري خدمات للمقارنة','Choose services to compare'),t('ابدئي من الاستكشاف.','Start by exploring services.')))}
function remaining(s){return s.capacity-bookings.filter(b=>b.slot===s.id&&['pending','confirmed','completed'].includes(b.status)).length}function available(id){return slots.filter(s=>s.service===id&&s.active&&remaining(s)>0)}let bookingSlot=null;
function book(id){selected=id;bookingSlot=null;const x=service(id),list=available(id);modal(`<div class="step-label">${t('01 اختيار الموعد ← 02 المراجعة','01 Choose a time → 02 Review')}</div><h2>${t('وقت مناسب لبداية جديدة','Make time for your next step')}</h2><p class="muted">${esc(text(x.name))} · ${money(x.price)} / ${unit(x.unit)}</p>${list.length?`<form onsubmit="reviewBooking(event)"><div class="field"><label for="bookslot">${t('الموعد المتاح','Available appointment')}</label><select id="bookslot" required><option value="">${t('اختاري موعدًا','Select a time')}</option>${list.map(s=>`<option value="${s.id}">${s.date} · ${s.time} · ${remaining(s)} ${t('أماكن','spaces')}</option>`).join('')}</select></div><p class="small-note">${t('المواعيد مرتبطة بلوحة المزوّد. الطلب لا يُؤكد تلقائيًا.','Times are linked to the provider calendar. Requests are not automatically confirmed.')}</p><button class="primary">${t('متابعة للمراجعة','Continue to review')}</button></form>`:empty(t('لا توجد مواعيد حاليًا','No times available'),t('يمكن إضافة موعد لهذه الخدمة من لوحة المزوّد.','A provider can add availability for this service.'))}`)}function reviewBooking(e){e.preventDefault();bookingSlot=+$('bookslot').value;const s=slots.find(a=>a.id===bookingSlot),x=service(selected);modal(`<div class="step-label">${t('01 الموعد ✓ ← 02 المراجعة','01 Time ✓ → 02 Review')}</div><h2>${t('راجعي تفاصيل الطلب','Review your request')}</h2><div class="summary">${esc(text(x.name))}<br>⌖ ${area(x.area)}<br>${s.date} · ${s.time}<br>${money(x.price)} / ${unit(x.unit)}<br>${t('الحالة: بانتظار الموافقة','Status: awaiting approval')}</div><p class="small-note">${t('طلب تجريبي محفوظ محليًا. لا دفع أو حجز فعلي.','A local demo request. No real reservation or payment.')}</p><button class="primary" onclick="confirmBooking()">${t('تأكيد الطلب التجريبي','Confirm demo request')}</button> <button class="secondary" onclick="book(${selected})">${t('رجوع','Back')}</button>`)}function confirmBooking(){let s=slots.find(x=>x.id===bookingSlot),x=service(selected);if(!s||!s.active||remaining(s)<=0||x.status!=='approved'){closeModal();toast(t('الموعد لم يعد متاحًا. اختاري موعدًا آخر.','This time is no longer available. Please choose another.'));return}bookings.push({id:Date.now(),service:x.id,slot:s.id,date:s.date,time:s.time,price:x.price,status:'pending',review:null});persist();navto('bookings');toast(t('تم إرسال الطلب التجريبي للمزوّد','Demo request sent to the provider workspace'))}
function bookingRows(list,manage=false){return list.length?list.map(b=>`<div class="booking-item"><div><b>${esc(text(service(b.service)?.name))}</b><p class="muted">${b.date} · ${b.time} · ${money(b.price)}</p>${pill(b.status)}</div><div class="action-row">${manage&&b.status==='pending'?`<button class="primary" onclick="updateBooking(${b.id},'confirmed')">${t('قبول','Accept')}</button><button class="secondary" onclick="confirmCancel(${b.id})">${t('رفض الطلب','Decline')}</button>`:''}${manage&&b.status==='confirmed'?`<button class="primary" onclick="updateBooking(${b.id},'completed')">${t('تحديد كمكتمل','Mark completed')}</button>`:''}${!manage&&['pending','confirmed'].includes(b.status)?`<button class="secondary" onclick="confirmCancel(${b.id})">${t('إلغاء الطلب','Cancel request')}</button>`:''}${!manage&&b.status==='completed'&&!b.review?`<button class="secondary" onclick="reviewForm(${b.id})">${t('إضافة تقييم','Leave a review')}</button>`:''}${b.review?`<span class="small-note">${b.review.rating} / 5 · ${esc(b.review.comment)}</span>`:''}</div></div>`).join(''):empty(t('لا توجد حجوزات بعد','No bookings yet'),t('ابدئي باختيار خدمة وموعد من تجربة المستخدم.','Choose a service and a time from the user experience.'))}function updateBooking(id,s){bookings=bookings.map(b=>b.id===id?{...b,status:s}:b);persist();render();toast(t('تم تحديث حالة الحجز في الواجهتين','Booking status updated in both workspaces'))}function confirmCancel(id){modal(`<h2>${t('تأكيد إلغاء الطلب؟','Cancel this request?')}</h2><p class="muted">${t('سيتم تحرير المكان في جدول المواعيد.','The space will become available again.')}</p><button class="primary" onclick="updateBooking(${id},'cancelled');closeModal()">${t('تأكيد الإلغاء','Confirm cancellation')}</button> <button class="secondary" onclick="closeModal()">${t('احتفاظ بالطلب','Keep request')}</button>`)}function reviewForm(id){modal(`<h2>${t('كيف كانت التجربة؟','How was your experience?')}</h2><form onsubmit="saveReview(event,${id})"><div class="field"><label for="rr">${t('التقييم من 5','Rating out of 5')}</label><select id="rr">${[5,4,3,2,1].map(n=>`<option>${n}</option>`).join('')}</select><label for="rc">${t('تعليقك','Your review')}</label><textarea id="rc" maxlength="300" required></textarea></div><button class="primary">${t('حفظ التقييم التجريبي','Save demo review')}</button></form>`)}function saveReview(e,id){e.preventDefault();bookings.find(b=>b.id===id).review={rating:+$('rr').value,comment:$('rc').value,visible:true};persist();closeModal();render()}
function prefs(){const p=read('fp2-prefs',{goal:'fitness',area:'marj'});return title('رحلتك، <span>على طريقتك.</span>','Your journey. <span>Your preferences.</span>','التفضيلات محفوظة محليًا؛ بدون بيانات صحية أو تشغيل للميكروفون.','Preferences are saved locally. No health data or microphone access.')+`<form class="panel" onsubmit="savePrefs(event)"><div class="form-grid"><div class="field"><label for="pg">${t('هدفك','Your goal')}</label><select id="pg">${[['fitness',t('بداية نشاط منتظم','Build an active routine')],['nutrition',t('عادات غذائية أفضل','Better eating habits')],['strength',t('تحسين اللياقة','Improve fitness')]].map(([v,l])=>`<option value="${v}" ${p.goal===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="pa">${t('المنطقة المفضلة','Preferred area')}</label><select id="pa">${['marj','abdoun','khalda','online'].map(a=>`<option value="${a}" ${p.area===a?'selected':''}>${area(a)}</option>`).join('')}</select></div></div><p class="small-note">${t('لا توجد ذاكرة AI أو متابعة تلقائية مفعلة في هذا النموذج.','AI memory and proactive follow-ups are not enabled in this prototype.')}</p><button class="primary">${t('حفظ التفضيلات','Save preferences')}</button></form>`}function savePrefs(e){e.preventDefault();write('fp2-prefs',{goal:$('pg').value,area:$('pa').value});toast(t('تم حفظ التفضيلات','Preferences saved'))}
const myIds=()=>services.filter(x=>x.cat===providerType).map(x=>x.id),myBookings=()=>bookings.filter(b=>myIds().includes(b.service));function stats(items){return `<div class="stats">${items.map(([n,l])=>`<div class="stat"><small>${l}</small><strong>${n}</strong></div>`).join('')}</div>`}
function providerOverview(){let b=myBookings();return title('كل تفاصيل شغلك، <span>بمكان واحد.</span>','Your workday, <span>all in one place.</span>','ابدئي بالطلبات التي تحتاج قرارك، ثم رتّبي خدماتك ومواعيدك.','Start with requests needing a decision, then organize services and availability.')+stats([[b.filter(x=>x.status==='pending').length,t('طلبات بانتظار قرارك','Requests awaiting your decision')],[b.filter(x=>x.status==='confirmed').length,t('حجوزات مؤكدة','Confirmed bookings')],[services.filter(x=>x.cat===providerType).length,t('خدمات في حساب العرض','Services in this demo account')]])+`<div class="action-row"><button class="primary" onclick="navto('availability');slotForm()">＋ ${t('إضافة موعد','Add availability')}</button><button class="secondary" onclick="navto('services');serviceForm()">＋ ${t('إضافة خدمة','Add a service')}</button></div><div class="section-title"><h2>${t('طلبات تحتاج انتباهك','Requests that need your attention')}</h2><button onclick="navto('requests')">${t('كل الحجوزات','All bookings')}</button></div>${b.some(x=>x.status==='pending')?bookingRows(b.filter(x=>x.status==='pending'),true):empty(t('كل الطلبات مُراجعة','All caught up'),t('ما في طلبات بانتظار قرارك حاليًا.','No requests are awaiting your decision.'))}<div class="panel"><h2>${t('المواعيد القادمة','Upcoming availability')}</h2><div class="schedule">${slots.filter(s=>myIds().includes(s.service)&&s.active).slice(0,6).map(s=>`<div><b>${s.date}</b><p>${s.time}</p><small>${esc(text(service(s.service)?.name))}</small></div>`).join('')||t('أضيفي أول موعد متاح.','Add your first available time.')}</div></div>`}
function chooseProviderType(c){write('fp2-profile-'+providerType,profile);providerType=c;write('fp2-provider-type',c);const x=services.find(x=>x.cat===c);profile=read('fp2-profile-'+c,{name:{...x.name},bio:{...x.desc},qualification:pair('مؤهلات تجريبية غير موثقة','Illustrative unverified credentials'),capacity:x.capacity||1,mode:c==='trainer'?'online':'inperson'});render()}
function profileView(){return title('ملف يعرّف الناس <span>عليك.</span>','A profile that <span>introduces you.</span>','الحقول تتغيّر حسب نوع مزوّد الخدمة.','Fields adapt to the provider category.')+`<form class="panel" onsubmit="saveProfile(event)"><div class="field"><label for="ptype">${t('نوع حساب العرض','Demo provider type')}</label><select id="ptype" onchange="chooseProviderType(this.value)">${['gym','diet','trainer'].map(c=>`<option value="${c}" ${c===providerType?'selected':''}>${cat(c)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="pna">${t('الاسم بالعربية','Arabic name')}</label><input id="pna" value="${esc(profile.name.ar)}" required maxlength="80"></div><div class="field"><label for="pne">${t('الاسم بالإنجليزية','English name')}</label><input id="pne" value="${esc(profile.name.en)}" required maxlength="80"></div><div class="field"><label for="pba">${t('الوصف بالعربية','Arabic description')}</label><textarea id="pba" required>${esc(profile.bio.ar)}</textarea></div><div class="field"><label for="pbe">${t('الوصف بالإنجليزية','English description')}</label><textarea id="pbe" required>${esc(profile.bio.en)}</textarea></div>${providerType==='gym'?`<div class="field"><label for="pcap">${t('السعة الافتراضية للحصة','Default class capacity')}</label><input type="number" min="1" max="100" id="pcap" value="${profile.capacity}" required></div><div class="field"><label for="facility">${t('الأنشطة والمرافق','Activities & facilities')}</label><input id="facility" value="${esc(read('fp2-facility',t('بيلاتس، غرف تبديل','Pilates, changing rooms')))}"></div>`:`<div class="field"><label for="pq">${providerType==='diet'?t('المؤهلات وتخصص التغذية','Qualifications & nutrition specialty'):t('الشهادات وتخصص التدريب','Certifications & training specialty')}</label><input id="pq" value="${esc(text(profile.qualification))}" required></div><div class="field"><label for="pm">${t('طريقة تقديم الخدمة','Delivery mode')}</label><select id="pm"><option value="online" ${profile.mode==='online'?'selected':''}>${t('أونلاين','Online')}</option>${providerType==='diet'?`<option value="inperson" ${profile.mode==='inperson'?'selected':''}>${t('حضوري','In person')}</option><option value="both" ${profile.mode==='both'?'selected':''}>${t('كلاهما','Both')}</option>`:''}</select></div>`}</div><p class="small-note">${t('حفظ الاسم والوصف يحدّث أول خدمة من النوع المحدد في كتالوج المستخدم. حسابات العرض ليست حسابات مستقلة أو صلاحيات أمنية.','Saving updates the first service in this category in the user catalogue. Demo roles are not separate accounts or security permissions.')}</p><button class="primary">${t('حفظ الملف','Save profile')}</button></form>`}
function saveProfile(e){e.preventDefault();profile.name=pair($('pna').value,$('pne').value);profile.bio=pair($('pba').value,$('pbe').value);if($('pcap'))profile.capacity=+$('pcap').value;if($('facility'))write('fp2-facility',$('facility').value);if($('pq'))profile.qualification[lang]=$('pq').value;if($('pm'))profile.mode=$('pm').value;let x=services.find(x=>x.cat===providerType);if(x){x.name={...profile.name};x.desc={...profile.bio}}persist();write('fp2-profile-'+providerType,profile);toast(t('تم تحديث الملف والكتالوج','Profile and catalogue updated'))}
function providerServices(){return title('خدمات واضحة، <span>وأسعار أوضح.</span>','Clear services. <span>Clearer pricing.</span>','التعديلات تظهر مباشرة في تجربة المستخدم.','Changes appear immediately in the user experience.')+`<div class="section-title"><h2>${cat(providerType)}</h2><button class="primary" onclick="serviceForm()">＋ ${t('إضافة خدمة','Add service')}</button></div>${services.filter(x=>x.cat===providerType).map(x=>`<div class="booking-item"><div><b>${esc(text(x.name))}</b><p class="muted">${money(x.price)} / ${unit(x.unit)} · ${x.duration} ${t('دقيقة','min')}</p>${pill(x.status)}</div><div class="action-row"><button class="secondary" onclick="serviceForm(${x.id})">${t('تعديل','Edit')}</button><button class="secondary" onclick="toggleService(${x.id})">${x.status==='approved'?t('إيقاف الظهور','Pause listing'):t('إعادة الظهور','Restore listing')}</button></div></div>`).join('')}`}
function serviceForm(id){let x=service(id)||{name:pair('',''),desc:pair('',''),price:30,duration:50,unit:providerType==='diet'?'consultation':providerType==='trainer'?'session':'class',area:providerType==='trainer'?'online':'marj'};modal(`<h2>${id?t('تعديل الخدمة','Edit service'):t('إضافة خدمة جديدة','Add a service')}</h2><form onsubmit="saveService(event,${id||0})"><div class="form-grid"><div class="field"><label for="sna">${t('اسم الخدمة بالعربية','Arabic service name')}</label><input id="sna" value="${esc(x.name.ar)}" maxlength="80" required></div><div class="field"><label for="sne">${t('اسم الخدمة بالإنجليزية','English service name')}</label><input id="sne" value="${esc(x.name.en)}" maxlength="80" required></div><div class="field"><label for="spr">${t('السعر بالدينار','Price in JOD')}</label><input id="spr" type="number" min="0" step="0.01" value="${x.price}" required></div><div class="field"><label for="sun">${t('وحدة السعر','Pricing unit')}</label><select id="sun">${['class','consultation','session','month'].map(u=>`<option value="${u}" ${u===x.unit?'selected':''}>${unit(u)}</option>`).join('')}</select></div><div class="field"><label for="sdu">${t('المدة بالدقائق','Duration in minutes')}</label><input id="sdu" type="number" min="1" max="480" value="${x.duration}" required></div><div class="field"><label for="sar">${t('المنطقة','Area')}</label><select id="sar">${['marj','abdoun','khalda','online'].map(a=>`<option value="${a}" ${x.area===a?'selected':''}>${area(a)}</option>`).join('')}</select></div><div class="field"><label for="sda">${t('الوصف بالعربية','Arabic description')}</label><textarea id="sda" required>${esc(x.desc.ar)}</textarea></div><div class="field"><label for="sde">${t('الوصف بالإنجليزية','English description')}</label><textarea id="sde" required>${esc(x.desc.en)}</textarea></div></div><button class="primary">${t('حفظ وإظهار للمستخدم','Save to user catalogue')}</button></form>`)}
function saveService(e,id){e.preventDefault();let values={name:pair($('sna').value,$('sne').value),desc:pair($('sda').value,$('sde').value),price:+$('spr').value,unit:$('sun').value,duration:+$('sdu').value,area:$('sar').value};if(id)Object.assign(service(id),values);else services.push({...values,id:Date.now(),cat:providerType,activity:providerType==='gym'?'fitness':providerType==='diet'?'nutrition':'training',tags:[pair('خدمة مضافة من المزوّد','Added by provider')],status:'approved',capacity:providerType==='gym'?profile.capacity:1});persist();closeModal();render();toast(t('تم حفظ الخدمة في الكتالوج','Service saved to the catalogue'))}function toggleService(id){service(id).status=service(id).status==='approved'?'paused':'approved';persist();render()}
function availabilityView(){return title('رتّبي وقتك، <span>بكل وضوح.</span>','Your schedule, <span>clearly organized.</span>','المواعيد والسعة مرتبطة بنموذج الحجز عند المستخدم.','Availability and capacity are linked to the user booking flow.')+`<div class="section-title"><h2>${t('المواعيد المتاحة','Availability')}</h2><button class="primary" onclick="slotForm()">＋ ${t('إضافة موعد','Add a time')}</button></div>${slots.filter(s=>myIds().includes(s.service)).map(s=>`<div class="booking-item"><div><b>${esc(text(service(s.service)?.name))}</b><p class="muted">${s.date} · ${s.time} · ${remaining(s)} / ${s.capacity} ${t('أماكن متبقية','spaces left')}</p><span class="status">${s.active?t('متاح للحجز','Open for booking'):t('مغلق للحجوزات الجديدة','Closed to new bookings')}</span></div><button class="secondary" onclick="toggleSlot(${s.id})">${s.active?t('إغلاق الموعد','Close time'):t('فتح الموعد','Open time')}</button></div>`).join('')||empty(t('لا توجد مواعيد','No availability yet'),t('أضيفي أول موعد لخدمتك.','Add a time for your service.'))}`}
function slotForm(){modal(`<h2>${t('إضافة موعد متاح','Add availability')}</h2><form onsubmit="saveSlot(event)"><div class="field"><label for="ssl">${t('الخدمة','Service')}</label><select id="ssl" required>${services.filter(x=>x.cat===providerType&&x.status==='approved').map(x=>`<option value="${x.id}">${esc(text(x.name))}</option>`).join('')}</select><label for="sdate">${t('التاريخ','Date')}</label><input id="sdate" type="date" min="2026-11-01" required><label for="stime">${t('الوقت','Time')}</label><input id="stime" type="time" required><label for="scap">${t('السعة','Capacity')}</label><input id="scap" type="number" min="1" max="100" value="${providerType==='gym'?profile.capacity:1}" ${providerType!=='gym'?'readonly':''} required></div><p class="small-note">${t('هذا الجدول محاكاة محلية، وليس تقويمًا متصلًا بمنشأة حقيقية.','This is a local demo calendar, not a real provider schedule.')}</p><button class="primary">${t('إضافة الموعد','Add time')}</button></form>`)}
function saveSlot(e){e.preventDefault();const id=+$('ssl').value,date=$('sdate').value,time=$('stime').value;if(slots.some(s=>s.service===id&&s.date===date&&s.time===time))return toast(t('الموعد موجود بالفعل','This time already exists'));slots.push({id:Date.now(),service:id,date,time,capacity:+$('scap').value,active:true});persist();closeModal();render();toast(t('الموعد ظاهر الآن في صفحة الخدمة','This time is now visible on the service page'))}function toggleSlot(id){let s=slots.find(s=>s.id===id);s.active=!s.active;persist();render()}
function adminOverview(){return title('منصة أوضح، <span>وثقة أكبر.</span>','A clearer platform. <span>Greater confidence.</span>','ابدئي بما يحتاج مراجعتك، بدل التنقل بين قوائم طويلة.','Start with decisions that need your attention.')+stats([[applications.filter(a=>a.status==='pending').length,t('طلبات جديدة','New applications')],[applications.filter(a=>a.status==='needs_info').length,t('ملفات بحاجة لاستكمال','Applications needing information')],[bookings.filter(b=>b.review?.visible).length,t('تقييمات منشورة تجريبيًا','Published demo reviews')]])+`<div class="action-row"><button class="primary" onclick="navto('applications')">${t('مراجعة طلبات الانضمام','Review applications')}</button><button class="secondary" onclick="navto('moderation')">${t('مراجعة التقييمات','Review feedback')}</button></div><div class="section-title"><h2>${t('بانتظار المراجعة','Awaiting review')}</h2></div>${applicationRows(applications.filter(a=>['pending','needs_info'].includes(a.status)))}`}
function applicationRows(list){return list.map(a=>`<div class="booking-item"><div><b>${esc(text(a.name))}</b><p class="muted">${cat(a.cat)}</p>${pill(a.status)}</div><button class="secondary" onclick="reviewApplication(${a.id})">${t('فتح الملف','Open application')}</button></div>`).join('')||empty(t('كل الطلبات مُراجعة','All caught up'),t('لا توجد طلبات جديدة.','No new applications.'))}
function applicationsView(){return title('كل طلب، <span>بقرار واضح.</span>','Every application. <span>A clear decision.</span>','راجعي المعلومات والمستندات وسجّلي سبب القرار.','Review details and documents, and record the decision reason.')+applicationRows(applications)}
function reviewApplication(id){let a=applications.find(a=>a.id===id);modal(`<div class="step-label">${t('مراجعة مزوّد خدمة','PROVIDER REVIEW')}</div><h2>${esc(text(a.name))}</h2><p class="muted">${cat(a.cat)} · ${status(a.status)}</p><div class="review-evidence"><div>${t('بيانات التواصل: بيانات عرض غير حقيقية','Contact information: fictional demo details')}</div><div>${t('الموقع: عمّان، الأردن','Location: Amman, Jordan')}</div><div>${a.documents?t('المستند: مثال توضيحي متوفر، ليس مستندًا حقيقيًا','Document: illustrative example, not a real credential'):t('المستندات: ناقصة — القبول غير متاح قبل الاستكمال','Documents: missing — approval is disabled until completed')}</div></div><form onsubmit="decideApplication(event,${id})"><div class="field"><label for="decision">${t('القرار','Decision')}</label><select id="decision"><option value="needs_info">${t('طلب استكمال','Request information')}</option><option value="approved" ${!a.documents?'disabled':''}>${t('قبول تجريبي','Demo approval')}</option><option value="rejected">${t('رفض','Reject')}</option></select><label for="reason">${t('السبب أو المعلومات المطلوبة','Reason or requested information')}</label><textarea id="reason" required maxlength="400">${esc(a.note)}</textarea></div><button class="primary">${t('حفظ القرار','Save decision')}</button></form>`)}function decideApplication(e,id){e.preventDefault();let a=applications.find(a=>a.id===id);if($('decision').value==='approved'&&!a.documents)return;a.status=$('decision').value;a.note=$('reason').value;persist();closeModal();render();toast(t('تم حفظ القرار وسببه','Decision and reason saved'))}
function providersView(){return title('إدارة المزوّدين، <span>بصورة أوضح.</span>','Provider management, <span>at a glance.</span>','إيقاف الخدمة يخفيها من كتالوج المستخدم دون حذف حجوزاتها.','Pausing a listing hides it from discovery without deleting bookings.')+services.map(x=>`<div class="booking-item"><div><b>${esc(text(x.name))}</b><p class="muted">${cat(x.cat)} · ${area(x.area)}</p>${pill(x.status)}</div><button class="secondary" onclick="toggleService(${x.id})">${x.status==='approved'?t('إيقاف الظهور','Pause listing'):t('إعادة الظهور','Restore listing')}</button></div>`).join('')}
function usersView(){let active=read('fp2-demo-user-active',true);return title('المستخدمون، <span>وحالة حساباتهم.</span>','Users and <span>account status.</span>','صفحة إدارة توضيحية؛ لا توجد حسابات فعلية أو نظام صلاحيات متصل.','Illustrative management page. No real accounts or connected authorization system.')+`<div class="booking-item"><div><b>${t('المستخدم التجريبي','Demo user')}</b><p class="muted">${bookings.length} ${t('طلبات حجز محلية','local booking requests')}</p>${pill(active?'active':'paused')}</div><button class="secondary" onclick="write('fp2-demo-user-active',${!active});render();toast(t('تم تحديث حالة حساب العرض فقط','Demo account status updated only'))">${active?t('تعطيل تجريبي','Demo deactivate'):t('إعادة تفعيل','Reactivate')}</button></div><p class="status-note">${t('تغيير الحالة هنا لعرض التصميم فقط، ولا يفرض صلاحيات أو يمنع استخدام النموذج.','This status control demonstrates the design only. It does not enforce permissions or restrict prototype access.')}</p>`}
function moderationView(){let list=bookings.filter(b=>b.review);return title('محتوى مرتب، <span>وتجربة موثوقة.</span>','Organized content. <span>A trustworthy experience.</span>','تصنيفات ثابتة وتقييمات ناتجة عن الحجوزات المكتملة فقط.','Fixed categories and reviews from completed demo bookings only.')+`<div class="panel"><h2>${t('تصنيفات الخدمات','Service categories')}</h2><div class="chips">${['gym','diet','trainer'].map(c=>`<span class="chip">${cat(c)}</span>`).join('')}</div><p class="small-note">${t('التصنيفات ثابتة في هذا النموذج للحفاظ على ترابط البيانات.','Categories are fixed in this prototype to preserve data consistency.')}</p></div><div class="section-title"><h2>${t('مراجعة التقييمات','Review moderation')}</h2></div>${list.length?list.map(b=>`<div class="booking-item"><div><b>${esc(text(service(b.service)?.name))} · ${b.review.rating} / 5</b><p>${esc(b.review.comment)}</p><span class="status">${b.review.visible?t('ظاهر','Visible'):t('مخفي','Hidden')}</span></div><button class="secondary" onclick="toggleReview(${b.id})">${b.review.visible?t('إخفاء التقييم','Hide review'):t('إظهار التقييم','Show review')}</button></div>`).join(''):empty(t('لا توجد تقييمات بعد','No reviews yet'),t('تظهر هنا بعد إكمال حجز وإضافة تقييم من المستخدم.','Reviews appear after a booking is completed and the user leaves feedback.'))}`}
function toggleReview(id){let r=bookings.find(b=>b.id===id).review;r.visible=!r.visible;persist();render()}
let lastFocus=null;function modal(html){lastFocus=document.activeElement;$('overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${t('نافذة تفاعلية','Interactive dialog')}"><button class="close" onclick="closeModal()" aria-label="${t('إغلاق','Close')}">×</button>${html}</section></div>`;$('overlay').querySelector('button')?.focus()}function closeModal(){$('overlay').innerHTML='';lastFocus?.isConnected&&lastFocus.focus()}
const welcomeText=()=>t('أهلًا وسهلًا! أنا نوفا، مساعدتك الشخصية في فيت باث. يلا نبلّش رحلتك نحو حياة أكثر صحة ونشاط! كيف بقدر أساعدك اليوم؟ بدك نلاقي جيم، أخصائي تغذية، أو مدرّبك الشخصي؟','Welcome! I’m Nova, your personal FitPath assistant. Let’s begin your journey towards a healthier, more active life. How can I help you today? Shall we find a gym, a dietitian, or your personal trainer?');let speechTimer=null;
let speechSequence=0,needsVoiceGesture=false,voiceAttempted=false;
function stopVoice(){speechSequence++;clearTimeout(speechTimer);voiceState='idle';needsVoiceGesture=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));voiceFeedback(t('نوفا جاهزة لمساعدتك','Nova is ready to help'))}
function voiceFeedback(s){const e=$('voice-status');if(e)e.textContent=s}
function speakWelcome(){
 stopVoice();voiceAttempted=true;
 if(!('speechSynthesis'in window)){voiceFeedback(t('أهلًا فيكِ! صوت نوفا غير متاح على هذا الجهاز.','Welcome! Nova’s voice is unavailable on this device.'));return}
 const sequence=speechSequence,u=new SpeechSynthesisUtterance(welcomeText());u.lang=lang==='ar'?'ar-JO':'en-US';u.rate=lang==='ar'?.94:.96;
 const voices=speechSynthesis.getVoices(),v=voices.find(v=>v.lang.toLowerCase()===(lang==='ar'?'ar-jo':'en-us'))||voices.find(v=>v.lang.toLowerCase().startsWith(lang));if(v)u.voice=v;
 voiceState='starting';voiceFeedback(t('نوفا ترحّب فيكِ…','Nova is welcoming you…'));
 const blocked=()=>{if(sequence!==speechSequence)return;voiceState='waiting';needsVoiceGesture=true;document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));voiceFeedback(t('أهلًا فيكِ! الصوت يبدأ مع أول تفاعل إذا سمح جهازك.','Welcome! Audio starts with your first interaction if supported.'))};
 u.onstart=()=>{if(sequence!==speechSequence)return;clearTimeout(speechTimer);voiceState='speaking';needsVoiceGesture=false;document.querySelectorAll('.nova-scene,.nova-live').forEach(e=>e.classList.add('speaking'));voiceFeedback(t('نوفا بتحكي معكِ…','Nova is speaking to you…'))};
 u.onend=()=>{if(sequence!==speechSequence)return;voiceState='idle';needsVoiceGesture=false;document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));voiceFeedback(t('أنا هون، احكيلي كيف بقدر أساعدك','I’m here. How can I help you?'))};
 u.onerror=blocked;try{speechSynthesis.speak(u)}catch{blocked()}
 speechTimer=setTimeout(()=>{if(sequence===speechSequence&&voiceState==='starting'){speechSynthesis.cancel();blocked()}},4500)
}
function firstVoiceInteraction(){if(role==='user'&&page==='home'&&needsVoiceGesture)speakWelcome()}
document.addEventListener('pointerdown',firstVoiceInteraction,{passive:true});document.addEventListener('keydown',e=>{if(['Enter',' ','Tab'].includes(e.key))firstVoiceInteraction()});
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',()=>{if(role==='user'&&page==='home'&&voiceAttempted&&voiceState==='waiting'&&speechSynthesis.getVoices().some(v=>v.lang.startsWith(lang)))speakWelcome()},{once:true});
function render(){shell();const views=role==='user'?{home,chat,discover,detail:details,compare:compareView,saved:()=>title('خياراتك الحلوة، <span>بمكان واحد.</span>','Your favourites, <span>all together.</span>','ارجعي للخيارات المحفوظة بأي وقت.','Return to your saved options anytime.')+'<div style="margin-top:25px">'+cards(services.filter(x=>favorites.includes(x.id)&&x.status==='approved'))+'</div>',bookings:()=>title('موعدك مع <span>خطوة جديدة.</span>','Your next step <span>is taking shape.</span>','الطلبات وحالتها مرتبطة بلوحة المزوّد على هذا المتصفح.','Requests and status are connected to the provider workspace on this browser.')+bookingRows(bookings),preferences:prefs}:role==='provider'?{overview:providerOverview,profile:profileView,services:providerServices,availability:availabilityView,requests:()=>title('كل حجز، <span>بخطوة واضحة.</span>','Every booking. <span>A clear next step.</span>','قبول الطلب يحدّث الحالة عند المستخدم، والإلغاء يحرّر المكان.','Acceptance updates the user’s status; cancellation releases capacity.')+bookingRows(myBookings(),true)}:{overview:adminOverview,applications:applicationsView,providers:providersView,users:usersView,moderation:moderationView};$('app').innerHTML=(views[page]||views[role==='user'?'home':'overview'])()+note();if(role==='user'&&page==='detail'){const reviews=bookings.filter(b=>b.service===selected&&b.review?.visible);if(reviews.length)$('app').insertAdjacentHTML('beforeend','<div class=panel><h2>'+t('تقييمات التجربة','Demo reviews')+'</h2>'+reviews.map(b=>'<p>'+b.review.rating+' / 5 · '+esc(b.review.comment)+'</p>').join('')+'</div>')}if(voiceState==='speaking')document.querySelectorAll('.nova-scene,.nova-live').forEach(e=>e.classList.add('speaking'));$('comparebar').innerHTML=role==='user'&&compare.length&&page!=='compare'?`<div class="comparebar">${compare.length} ${t('خدمات للمقارنة','services to compare')}<button onclick="navto('compare')">${t('قارني الآن ←','Compare now →')}</button><button aria-label="${t('مسح المقارنة','Clear comparison')}" onclick="compare=[];render()">×</button></div>`:''}
function route(){let [r,p]=location.hash.slice(1).split('/');if(['user','provider','admin'].includes(r)){role=r;page=p||(r==='user'?'home':'overview')}else{role='user';page='home'}render()}
window.addEventListener('hashchange',()=>{if(location.hash==='#'+role+'/'+page)return;closeModal();route()});window.addEventListener('storage',e=>{if(e.key?.startsWith('fp2-')){services=read('fp2-services',initial);slots=read('fp2-slots',[]);bookings=read('fp2-bookings',[]);favorites=read('fp2-favorites',[]);applications=read('fp2-apps',[]);render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('overlay').children.length){let a=[...$('overlay').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled),f=a[0],l=a[a.length-1];if(e.shiftKey&&document.activeElement===f){e.preventDefault();l.focus()}else if(!e.shiftKey&&document.activeElement===l){e.preventDefault();f.focus()}}});
